1	import {
2	  createContext,
3	  useContext,
4	  useEffect,
5	  useState,
6	  useCallback,
7	  type ReactNode,
8	} from "react";
9	import type { User, AuthError } from "@supabase/supabase-js";
10	import supabase from "@/lib/supabase";
11	import type { UserProfile } from "@/types/index";
12	
13	// ── Types ─────────────────────────────────────────────────────
14	
15	const ACTIVE_TEAM_KEY = "convertscan:active_team";
16	
17	interface AuthContextValue {
18	  user: User | null;
19	  profile: UserProfile | null;
20	  loading: boolean;
21	  activeTeamId: string | null;
22	  switchTeam: (teamId: string | null) => void;
23	  signIn: (email: string, password: string) => Promise<{ error: AuthError | null }>;
24	  signUp: (
25	    email: string,
26	    password: string,
27	    fullName: string
28	  ) => Promise<{ error: AuthError | null }>;
29	  signInWithGoogle: () => Promise<{ error: AuthError | null }>;
30	  signOut: () => Promise<void>;
31	  refreshProfile: () => Promise<void>;
32	}
33	
34	// ── Context ───────────────────────────────────────────────────
35	
36	const AuthContext = createContext<AuthContextValue | null>(null);
37	
38	// ── Provider ──────────────────────────────────────────────────
39	
40	export function AuthProvider({ children }: { children: ReactNode }) {
41	  const [user, setUser] = useState<User | null>(null);
42	  const [profile, setProfile] = useState<UserProfile | null>(null);
43	  const [loading, setLoading] = useState(true);
44	  const [activeTeamId, setActiveTeamId] = useState<string | null>(() =>
45	    localStorage.getItem(ACTIVE_TEAM_KEY)
46	  );
47	
48	  const switchTeam = useCallback((teamId: string | null) => {
49	    setActiveTeamId(teamId);
50	    if (teamId) {
51	      localStorage.setItem(ACTIVE_TEAM_KEY, teamId);
52	    } else {
53	      localStorage.removeItem(ACTIVE_TEAM_KEY);
54	    }
55	  }, []);
56	
57	  const fetchProfile = useCallback(async (userId: string) => {
58	    const { data, error } = await supabase
59	      .from("profiles")
60	      .select(
61	        "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, role, is_banned, created_at, billing_cycle_end"
62	      )
63	      .eq("id", userId)
64	      .single();
65	
66	    if (error) {
67	      console.error("Failed to fetch profile:", error.message);
68	      setProfile(null);
69	      return;
70	    }
71	
72	    setProfile(data as UserProfile);
73	  }, []);
74	
75	  const refreshProfile = useCallback(async () => {
76	    if (!user) return;
77	    await fetchProfile(user.id);
78	  }, [user, fetchProfile]);
79	
80	  useEffect(() => {
81	    // Resolve initial session without waiting for the listener
82	    supabase.auth.getSession().then(({ data: { session } }) => {
83	      setUser(session?.user ?? null);
84	      if (session?.user) {
85	        fetchProfile(session.user.id).finally(() => setLoading(false));
86	      } else {
87	        setLoading(false);
88	      }
89	    });
90	
91	    const {
92	      data: { subscription },
93	    } = supabase.auth.onAuthStateChange((_event, session) => {
94	      setUser(session?.user ?? null);
95	      if (session?.user) {
96	        fetchProfile(session.user.id);
97	      } else {
98	        setProfile(null);
99	      }
100	    });
101	
102	    return () => subscription.unsubscribe();
103	  }, [fetchProfile]);
104	
105	  // ── Auth actions ─────────────────────────────────────────────
106	
107	  const signIn = async (email: string, password: string) => {
108	    const { error } = await supabase.auth.signInWithPassword({ email, password });
109	    return { error };
110	  };
111	
112	  const signUp = async (email: string, password: string, fullName: string) => {
113	    const { error } = await supabase.auth.signUp({
114	      email,
115	      password,
116	      options: {
117	        data: { full_name: fullName },
118	        emailRedirectTo: `${window.location.origin}/auth/callback`,
119	      },
120	    });
121	    return { error };
122	  };
123	
124	  const signInWithGoogle = async () => {
125	    const { error } = await supabase.auth.signInWithOAuth({
126	      provider: "google",
127	      options: {
128	        redirectTo: `${window.location.origin}/auth/callback`,
129	      },
130	    });
131	    return { error };
132	  };
133	
134	  const signOut = async () => {
135	    await supabase.auth.signOut();
136	    setUser(null);
137	    setProfile(null);
138	    switchTeam(null);
139	  };
140	
141	  return (
142	    <AuthContext.Provider
143	      value={{
144	        user,
145	        profile,
146	        loading,
147	        activeTeamId,
148	        switchTeam,
149	        signIn,
150	        signUp,
151	        signInWithGoogle,
152	        signOut,
153	        refreshProfile,
154	      }}
155	    >
156	      {children}
157	    </AuthContext.Provider>
158	  );
159	}
160	
161	// ── Hook ──────────────────────────────────────────────────────
162	
163	export function useAuth(): AuthContextValue {
164	  const ctx = useContext(AuthContext);
165	  if (!ctx) {
166	    throw new Error("useAuth must be used inside <AuthProvider>");
167	  }
168	  return ctx;
169	}
