30	    }
31	  }, [user, loading, navigate, location.state]);
32	
33	  const handleSubmit = async (e: React.FormEvent) => {
34	    e.preventDefault();
35	
36	    if (!email.trim()) { toast.error("Email is required."); return; }
37	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast.error("Enter a valid email address."); return; }
38	    if (!password) { toast.error("Password is required."); return; }
39	    if (password.length < MIN_PASSWORD_LENGTH) { toast.error(`Password must be at least ${MIN_PASSWORD_LENGTH} characters.`); return; }
40	
41	    setSubmitting(true);
42	    const { error } = await signIn(email, password);
43	    setSubmitting(false);
44	
45	    if (error) {
