60	    // On success, the page navigates away via OAuth redirect — no further action needed.
61	  };
62	
63	  return (
64	    <div className="flex min-h-screen">
65	      {/* Left — Form */}
66	      <div className="flex flex-1 flex-col justify-center px-8 py-12 sm:px-16 lg:px-24">
67	        <div className="mx-auto w-full max-w-sm">
68	          {/* Logo */}
69	          <Link to="/" className="mb-10 flex items-center gap-2">
70	            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
71	              <ScanLine className="h-3.5 w-3.5 text-white" />
72	            </div>
73	            <span className="text-lg font-bold tracking-tight text-foreground">ConvertScan</span>
74	          </Link>
75	
76	          <h1 className="text-2xl font-bold text-foreground">Welcome back</h1>
77	          <p className="mt-1.5 text-sm text-muted-foreground">
78	            Log in to your account to continue
79	          </p>
80	
81	          {/* Google sign-in */}
82	          <Button
83	            variant="outline"
84	            className="mt-8 w-full border-border/50 py-5"
85	            onClick={handleGoogleLogin}
86	            disabled={googleLoading || submitting}
87	          >
88	            {googleLoading ? (
89	              <span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-muted-foreground border-t-transparent" />
90	            ) : (
91	              <svg className="mr-2 h-5 w-5" viewBox="0 0 24 24">
92	                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4"/>
93	                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
94	                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
95	                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
96	              </svg>
97	            )}
98	            Continue with Google
99	          </Button>
100	
101	          {/* Divider */}
102	          <div className="relative my-6">
103	            <Separator />
104	            <span className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-xs text-muted-foreground">
105	              or
106	            </span>
107	          </div>
108	
109	          {/* Email/password form */}
110	          <form onSubmit={handleSubmit} className="space-y-4">
111	            <div className="space-y-2">
112	              <Label htmlFor={emailId}>Email</Label>
113	              <Input
114	                id={emailId}
115	                type="email"
116	                placeholder="you@company.com"
117	                value={email}
118	                onChange={(e) => setEmail(e.target.value)}
119	                className="border-border/50"
120	                required
121	                disabled={submitting || googleLoading}
122	                autoComplete="email"
123	              />
124	            </div>
125	            <div className="space-y-2">
126	              <div className="flex items-center justify-between">
127	                <Label htmlFor={passwordId}>Password</Label>
128	                <Link to="/forgot-password" className="text-xs text-primary hover:underline">
129	                  Forgot password?
130	                </Link>
131	              </div>
132	              <Input
133	                id={passwordId}
134	                type="password"
135	                placeholder="Enter your password"
136	                value={password}
137	                onChange={(e) => setPassword(e.target.value)}
138	                className="border-border/50"
139	                required
140	                disabled={submitting || googleLoading}
141	                autoComplete="current-password"
142	              />
143	            </div>
144	            <Button
145	              type="submit"
146	              className="w-full py-5 font-semibold"
147	              disabled={submitting || googleLoading}
148	            >
149	              {submitting ? (
150	                <span className="flex items-center gap-2">
151	                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground border-t-transparent" />
152	                  Logging in…
153	                </span>
154	              ) : (
155	                "Log In"
156	              )}
157	            </Button>
158	          </form>
159	
160	          <p className="mt-6 text-center text-sm text-muted-foreground">
161	            Don't have an account?{" "}
162	            <Link to="/signup" className="font-medium text-primary hover:underline">
163	              Sign up
164	            </Link>
165	          </p>
166	        </div>
167	      </div>
168	
169	      {/* Right — Testimonial panel */}
170	      <div className="hidden w-2/5 xl:w-[45%] bg-gradient-to-br from-[hsl(222,47%,11%)] via-[hsl(222,47%,14%)] to-[hsl(222,47%,9%)] p-12 lg:flex lg:flex-col lg:justify-center">
171	        <div className="mx-auto max-w-md">
172	          <div className="flex gap-0.5 mb-6">
173	            {Array.from({ length: 5 }).map((_, i) => (
174	              <Star key={i} className="h-5 w-5 fill-amber-400 text-amber-400" />
175	            ))}
176	          </div>
177	          <blockquote className="text-xl font-medium leading-relaxed text-white">
178	            "ConvertScan found 12 issues on our landing page. After fixing just 3 of them, our conversion rate jumped 34%."
179	          </blockquote>
180	          <div className="mt-6 flex items-center gap-3">
181	            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10">
182	              <span className="text-sm font-bold text-white">SK</span>
183	            </div>
184	            <div>
185	              <p className="text-sm font-medium text-white">Sarah K.</p>
186	              <p className="text-sm text-muted-foreground">Marketing Manager at TechFlow</p>
187	            </div>
188	          </div>
189	        </div>
190	      </div>
191	    </div>
192	  );
193	};
194	
195	export default Login;
