1	import { useEffect, useId, useState } from "react";
2	import { Link, useNavigate, useSearchParams } from "react-router-dom";
3	import { ScanLine, Star } from "lucide-react";
4	import { Button } from "@/components/ui/button";
5	import { Input } from "@/components/ui/input";
6	import { Label } from "@/components/ui/label";
7	import { Separator } from "@/components/ui/separator";
8	import { toast } from "sonner";
9	import { useAuth } from "@/contexts/AuthContext";
10	
11	const REFERRAL_STORAGE_KEY = "convertscan:referral_code";
12	
13	const Signup = () => {
14	  const navigate = useNavigate();
15	  const [searchParams] = useSearchParams();
16	  const { user, signUp, signInWithGoogle, loading } = useAuth();
17	
18	  const nameId = useId();
19	  const emailId = useId();
20	  const passwordId = useId();
21	
22	  const [name, setName] = useState("");
23	  const [email, setEmail] = useState("");
24	  const [password, setPassword] = useState("");
25	  const [submitting, setSubmitting] = useState(false);
26	  const [googleLoading, setGoogleLoading] = useState(false);
27	
28	  // Build post-signup redirect destination from query params
29	  const redirectPath = searchParams.get("redirect");
30	  const redirectUrl = searchParams.get("url");
31	  const postSignupDest = redirectPath
32	    ? redirectUrl
33	      ? `${redirectPath}?url=${encodeURIComponent(redirectUrl)}`
34	      : redirectPath
35	    : "/dashboard";
36	
37	  // Capture ?ref= param on mount and persist to localStorage
38	  useEffect(() => {
39	    const refCode = searchParams.get("ref");
40	    if (refCode) {
41	      localStorage.setItem(REFERRAL_STORAGE_KEY, refCode);
42	    }
43	  }, [searchParams]);
44	
45	  // Redirect if already authenticated
46	  useEffect(() => {
47	    if (!loading && user) {
48	      navigate(postSignupDest, { replace: true });
49	    }
50	  }, [user, loading, navigate, postSignupDest]);
51	
52	  const handleSubmit = async (e: React.FormEvent) => {
53	    e.preventDefault();
54	
55	    if (!name.trim()) { toast.error("Name is required."); return; }
56	    if (!email.trim()) { toast.error("Email is required."); return; }
57	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast.error("Enter a valid email address."); return; }
58	    if (!password) { toast.error("Password is required."); return; }
59	    if (password.length < 8) { toast.error("Password must be at least 8 characters."); return; }
60	
61	    setSubmitting(true);
62	    const { error } = await signUp(email, password, name.trim());
63	    setSubmitting(false);
64	
65	    if (error) {
66	      toast.error(error.message ?? "Sign up failed. Please try again.");
67	      return;
68	    }
69	
70	    // Store email alongside the referral code so it can be processed
71	    // after the user confirms their email and the auth session is established.
72	    // The referral row creation is deferred to AuthContext's onAuthStateChange.
73	    const storedCode = localStorage.getItem(REFERRAL_STORAGE_KEY);
74	    if (storedCode) {
75	      localStorage.setItem(`${REFERRAL_STORAGE_KEY}:email`, email.trim());
76	    }
77	
78	    toast.success("Account created! Check your email to confirm your address.");
79	    navigate(postSignupDest, { replace: true });
80	  };
81	
82	  const handleGoogleSignup = async () => {
83	    setGoogleLoading(true);
84	    const { error } = await signInWithGoogle();
85	    if (error) {
86	      toast.error(error.message ?? "Google sign-in failed. Please try again.");
87	      setGoogleLoading(false);
88	    }
89	    // On success the page navigates away via OAuth redirect.
90	  };
91	
92	  return (
93	    <div className="flex min-h-screen">
94	      {/* Left — Form */}
95	      <div className="flex flex-1 flex-col justify-center px-8 py-12 sm:px-16 lg:px-24">
96	        <div className="mx-auto w-full max-w-sm">
97	          {/* Logo */}
98	          <Link to="/" className="mb-10 flex items-center gap-2">
99	            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
100	              <ScanLine className="h-3.5 w-3.5 text-white" />
101	            </div>
102	            <span className="text-lg font-bold tracking-tight text-foreground">ConvertScan</span>
103	          </Link>
104	
105	          <h1 className="text-2xl font-bold text-foreground">Create your account</h1>
106	          <p className="mt-1.5 text-sm text-muted-foreground">
107	            Start improving your conversions today
108	          </p>
109	
110	          {/* Google sign-up */}
111	          <Button
112	            variant="outline"
113	            className="mt-8 w-full border-border/50 py-5"
114	            onClick={handleGoogleSignup}
115	            disabled={googleLoading || submitting}
116	          >
117	            {googleLoading ? (
118	              <span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-muted-foreground border-t-transparent" />
119	            ) : (
120	              <svg className="mr-2 h-5 w-5" viewBox="0 0 24 24">
121	                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4"/>
122	                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
123	                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
124	                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
125	              </svg>
126	            )}
127	            Continue with Google
128	          </Button>
129	
130	          {/* Divider */}
131	          <div className="relative my-6">
132	            <Separator />
133	            <span className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-xs text-muted-foreground">
134	              or
135	            </span>
136	          </div>
137	
138	          {/* Form */}
139	          <form onSubmit={handleSubmit} className="space-y-4">
140	            <div className="space-y-2">
141	              <Label htmlFor={nameId}>Full Name</Label>
142	              <Input
143	                id={nameId}
144	                type="text"
145	                placeholder="John Doe"
146	                value={name}
147	                onChange={(e) => setName(e.target.value)}
148	                className="border-border/50"
149	                required
150	                disabled={submitting || googleLoading}
151	                autoComplete="name"
152	              />
153	            </div>
154	            <div className="space-y-2">
155	              <Label htmlFor={emailId}>Email</Label>
156	              <Input
157	                id={emailId}
158	                type="email"
159	                placeholder="you@company.com"
160	                value={email}
161	                onChange={(e) => setEmail(e.target.value)}
162	                className="border-border/50"
163	                required
164	                disabled={submitting || googleLoading}
165	                autoComplete="email"
166	              />
167	            </div>
168	            <div className="space-y-2">
169	              <Label htmlFor={passwordId}>Password</Label>
170	              <Input
171	                id={passwordId}
172	                type="password"
173	                placeholder="Create a password"
174	                value={password}
175	                onChange={(e) => setPassword(e.target.value)}
176	                className="border-border/50"
177	                required
178	                disabled={submitting || googleLoading}
179	                autoComplete="new-password"
180	              />
181	            </div>
182	            <Button
183	              type="submit"
184	              className="w-full py-5 font-semibold"
185	              disabled={submitting || googleLoading}
186	            >
187	              {submitting ? (
188	                <span className="flex items-center gap-2">
189	                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground border-t-transparent" />
190	                  Creating account…
191	                </span>
192	              ) : (
193	                "Create Account"
194	              )}
195	            </Button>
196	          </form>
197	
198	          <p className="mt-4 text-center text-xs text-muted-foreground">
199	            By signing up, you agree to our{" "}
200	            <Link to="/terms" className="text-primary hover:underline">Terms</Link> and{" "}
201	            <Link to="/privacy" className="text-primary hover:underline">Privacy Policy</Link>.
202	          </p>
203	
204	          <p className="mt-4 text-center text-sm text-muted-foreground">
205	            Already have an account?{" "}
206	            <Link to="/login" className="font-medium text-primary hover:underline">
207	              Log in
208	            </Link>
209	          </p>
