270	// ── Password strength helpers ───────────────────────────────────
271	
272	function getStrengthLevel(pw: string): number {
273	  let score = 0;
274	  if (pw.length >= 8) score++;
275	  if (pw.length >= 12) score++;
276	  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) score++;
277	  if (/\d/.test(pw) && /[^A-Za-z0-9]/.test(pw)) score++;
278	  return Math.min(score, 4);
279	}
280	
281	function getStrengthColor(level: number): string {
282	  if (level <= 1) return "bg-red-500";
283	  if (level === 2) return "bg-amber-500";
284	  if (level === 3) return "bg-yellow-400";
285	  return "bg-green-500";
286	}
287	
288	function getStrengthLabel(level: number): string {
289	  if (level <= 1) return "Weak password";
290	  if (level === 2) return "Fair password";
291	  if (level === 3) return "Good password";
292	  return "Strong password";
293	}
294	
295	export default ResetPassword;
