1	import { useEffect } from "react";
2	import { useNavigate } from "react-router-dom";
3	import supabase from "@/lib/supabase";
4	
5	const REFERRAL_STORAGE_KEY = "convertscan:referral_code";
6	
7	/**
8	 * Handles the OAuth / magic-link redirect from Supabase.
9	 * Supabase processes the URL hash automatically; we just wait
10	 * for the session to resolve and then forward the user.
11	 *
12	 * Also processes any pending referral created during signup:
13	 * reads convertscan:referral_code from localStorage and creates
14	 * the referral row if the code resolves to a valid referrer.
15	 */
16	export default function AuthCallback() {
17	  const navigate = useNavigate();
18	
19	  useEffect(() => {
20	    supabase.auth.getSession().then(async ({ data: { session } }) => {
21	      if (session) {
22	        // Process pending referral (best-effort, never blocks navigation)
23	        const storedCode = localStorage.getItem(REFERRAL_STORAGE_KEY);
24	        const storedEmail = localStorage.getItem(`${REFERRAL_STORAGE_KEY}:email`);
25	        if (storedCode && session.user) {
26	          try {
27	            const { data: referrer } = await supabase
28	              .from("profiles")
29	              .select("id")
30	              .eq("referral_code", storedCode)
31	              .single();
32	
33	            if (referrer && referrer.id !== session.user.id) {
34	              await supabase.from("referrals").insert({
35	                referrer_id: referrer.id,
36	                referred_email: storedEmail ?? session.user.email ?? "",
37	                referred_id: session.user.id,
38	                status: "signed_up",
39	              });
40	            }
41	          } catch {
42	            // Silently ignore — invalid code or duplicate insert
43	          } finally {
44	            localStorage.removeItem(REFERRAL_STORAGE_KEY);
45	            localStorage.removeItem(`${REFERRAL_STORAGE_KEY}:email`);
46	          }
47	        }
48	
49	        navigate("/dashboard", { replace: true });
50	      } else {
51	        navigate("/login", { replace: true });
52	      }
53	    });
54	  }, [navigate]);
55	
56	  return (
57	    <div className="flex min-h-screen items-center justify-center bg-background">
58	      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
59	    </div>
60	  );
61	}
