74	export function useTeams() {
75	  const { user } = useAuth();
76	
77	  return useQuery({
78	    queryKey: teamKeys.list(user?.id ?? ""),
79	    queryFn: async (): Promise<Team[]> => {
80	      if (!user?.id) return [];
81	
82	      const { data, error } = await supabase
83	        .from("team_members")
84	        .select("team_id, teams(*)")
85	        .eq("user_id", user.id)
86	        .order("joined_at", { ascending: true });
87	
88	      if (error) throw new Error(error.message);
89	
90	      return (data ?? [])
91	        .map((row) => {
92	          const team = (row as { team_id: string; teams: TeamRow | null }).teams;
93	          return team ? rowToTeam(team) : null;
94	        })
95	        .filter((t): t is Team => t !== null);
96	    },
97	    enabled: !!user?.id,
98	  });
99	}
