173	export function useCreateTeam() {
174	  const { user } = useAuth();
175	  const queryClient = useQueryClient();
176	
177	  return useMutation({
178	    mutationFn: async (name: string): Promise<Team> => {
179	      if (!user?.id) throw new Error("Not authenticated");
180	
181	      // Create team
182	      const { data: teamData, error: teamError } = await supabase
183	        .from("teams")
184	        .insert({ name, owner_id: user.id })
185	        .select("*")
186	        .single();
187	
188	      if (teamError) throw new Error(teamError.message);
189	
190	      const team = rowToTeam(teamData as TeamRow);
191	
192	      // Insert owner as team_member
193	      const { error: memberError } = await supabase
194	        .from("team_members")
195	        .insert({ team_id: team.id, user_id: user.id, role: "owner" });
196	
197	      if (memberError) throw new Error(memberError.message);
198	
199	      return team;
200	    },
201	    onSuccess: (data) => {
202	      if (!user?.id) return;
203	      queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
204	        prev ? [...prev, data] : [data]
205	      );
206	      queryClient.setQueryData(teamKeys.detail(data.id), data);
207	      toast.success(`Team "${data.name}" created`);
208	    },
209	    onError: (err: Error) => {
210	      toast.error(err.message);
211	    },
212	  });
213	}
