'use client'

import { useEffect, useId, useState } from 'react'
import Link from 'next/link'
import { useRouter, useSearchParams } from 'next/navigation'
import { ScanLine, Star } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { toast } from 'sonner'
import { useAuth } from '@/contexts/AuthContext'
import { MIN_PASSWORD_LENGTH } from '@/lib/constants'

export function LoginForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const { user, signIn, signInWithGoogle, loading } = useAuth()

  const emailId = useId()
  const passwordId = useId()

  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [googleLoading, setGoogleLoading] = useState(false)

  const redirectedFrom = searchParams.get('redirectedFrom') ?? '/dashboard'

  // Redirect if already authenticated
  useEffect(() => {
    if (!loading && user) {
      router.replace(redirectedFrom)
    }
  }, [user, loading, router, redirectedFrom])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!email.trim()) { toast.error('Email is required.'); return }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast.error('Enter a valid email address.'); return }
    if (!password) { toast.error('Password is required.'); return }
    if (password.length < MIN_PASSWORD_LENGTH) { toast.error(`Password must be at least ${MIN_PASSWORD_LENGTH} characters.`); return }

    setSubmitting(true)
    const { error } = await signIn(email, password)
    setSubmitting(false)

    if (error) {
      toast.error(error.message ?? 'Failed to log in. Please try again.')
      return
    }

    router.replace('/dashboard')
  }

  const handleGoogleLogin = async () => {
    setGoogleLoading(true)
    const { error } = await signInWithGoogle()
    if (error) {
      toast.error(error.message ?? 'Google sign-in failed. Please try again.')
      setGoogleLoading(false)
    }
    // On success, the page navigates away via OAuth redirect — no further action needed.
  }

  return (
    <div className="flex min-h-screen">
      {/* Left — Form */}
      <div className="flex flex-1 flex-col justify-center px-8 py-12 sm:px-16 lg:px-24">
        <div className="mx-auto w-full max-w-sm">
          {/* Logo */}
          <Link href="/" className="mb-10 flex items-center gap-2">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
              <ScanLine className="h-3.5 w-3.5 text-white" />
            </div>
            <span className="text-lg font-bold tracking-tight text-foreground">ConvertScan</span>
          </Link>

          <h1 className="text-2xl font-bold text-foreground">Welcome back</h1>
          <p className="mt-1.5 text-sm text-muted-foreground">
            Log in to your account to continue
          </p>

          {/* Google sign-in */}
          <Button
            variant="outline"
            className="mt-8 w-full border-border/50 py-5"
            onClick={handleGoogleLogin}
            disabled={googleLoading || submitting}
          >
            {googleLoading ? (
              <span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-muted-foreground border-t-transparent" />
            ) : (
              <svg className="mr-2 h-5 w-5" viewBox="0 0 24 24">
                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4"/>
                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
              </svg>
            )}
            Continue with Google
          </Button>

          {/* Divider */}
          <div className="relative my-6">
            <Separator />
            <span className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 bg-white px-3 text-xs text-muted-foreground">
              or
            </span>
          </div>

          {/* Email/password form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor={emailId}>Email</Label>
              <Input
                id={emailId}
                type="email"
                placeholder="you@company.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="border-border/50"
                required
                disabled={submitting || googleLoading}
                autoComplete="email"
              />
            </div>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label htmlFor={passwordId}>Password</Label>
                <Link href="/forgot-password" className="text-xs text-primary hover:underline">
                  Forgot password?
                </Link>
              </div>
              <Input
                id={passwordId}
                type="password"
                placeholder="Enter your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="border-border/50"
                required
                disabled={submitting || googleLoading}
                autoComplete="current-password"
              />
            </div>
            <Button
              type="submit"
              className="w-full py-5 font-semibold"
              disabled={submitting || googleLoading}
            >
              {submitting ? (
                <span className="flex items-center gap-2">
                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground border-t-transparent" />
                  Logging in&hellip;
                </span>
              ) : (
                'Log In'
              )}
            </Button>
          </form>

          <p className="mt-6 text-center text-sm text-muted-foreground">
            Don&apos;t have an account?{' '}
            <Link href="/signup" className="font-medium text-primary hover:underline">
              Sign up
            </Link>
          </p>
        </div>
      </div>

      {/* Right — Testimonial panel */}
      <div className="hidden w-2/5 xl:w-[45%] bg-gradient-to-br from-[hsl(222,47%,11%)] via-[hsl(222,47%,14%)] to-[hsl(222,47%,9%)] p-12 lg:flex lg:flex-col lg:justify-center">
        <div className="mx-auto max-w-md">
          <div className="flex gap-0.5 mb-6">
            {Array.from({ length: 5 }).map((_, i) => (
              <Star key={i} className="h-5 w-5 fill-amber-400 text-amber-400" />
            ))}
          </div>
          <blockquote className="text-xl font-medium leading-relaxed text-white">
            &ldquo;ConvertScan found 12 issues on our landing page. After fixing just 3 of them, our conversion rate jumped 34%.&rdquo;
          </blockquote>
          <div className="mt-6 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10">
              <span className="text-sm font-bold text-white">SK</span>
            </div>
            <div>
              <p className="text-sm font-medium text-white">Sarah K.</p>
              <p className="text-sm text-muted-foreground">Marketing Manager at TechFlow</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

