'use client'

import { useEffect, useId, useState } from 'react'
import Link from 'next/link'
import { useRouter, useSearchParams } from 'next/navigation'
import { ScanLine, Star } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { toast } from 'sonner'
import { useAuth } from '@/contexts/AuthContext'

const REFERRAL_STORAGE_KEY = 'convertscan:referral_code'

export function SignupForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const { user, signUp, signInWithGoogle, loading } = useAuth()

  const nameId = useId()
  const emailId = useId()
  const passwordId = useId()

  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [googleLoading, setGoogleLoading] = useState(false)

  // Build post-signup redirect destination from query params
  const redirectPath = searchParams.get('redirect')
  const redirectUrl = searchParams.get('url')
  const postSignupDest = redirectPath
    ? redirectUrl
      ? `${redirectPath}?url=${encodeURIComponent(redirectUrl)}`
      : redirectPath
    : '/dashboard'

  // Capture ?ref= param on mount and persist to localStorage
  useEffect(() => {
    const refCode = searchParams.get('ref')
    if (refCode) {
      localStorage.setItem(REFERRAL_STORAGE_KEY, refCode)
    }
  }, [searchParams])

  // Redirect if already authenticated
  useEffect(() => {
    if (!loading && user) {
      router.replace(postSignupDest)
    }
  }, [user, loading, router, postSignupDest])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!name.trim()) { toast.error('Name is required.'); return }
    if (!email.trim()) { toast.error('Email is required.'); return }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast.error('Enter a valid email address.'); return }
    if (!password) { toast.error('Password is required.'); return }
    if (password.length < 8) { toast.error('Password must be at least 8 characters.'); return }

    setSubmitting(true)
    const { error } = await signUp(email, password, name.trim())
    setSubmitting(false)

    if (error) {
      toast.error(error.message ?? 'Sign up failed. Please try again.')
      return
    }

    // Store email alongside the referral code so it can be processed
    // after the user confirms their email and the auth session is established.
    const storedCode = localStorage.getItem(REFERRAL_STORAGE_KEY)
    if (storedCode) {
      localStorage.setItem(`${REFERRAL_STORAGE_KEY}:email`, email.trim())
    }

    toast.success('Account created! Check your email to confirm your address.')
    router.replace(postSignupDest)
  }

  const handleGoogleSignup = async () => {
    setGoogleLoading(true)
    const { error } = await signInWithGoogle()
    if (error) {
      toast.error(error.message ?? 'Google sign-in failed. Please try again.')
      setGoogleLoading(false)
    }
    // On success the page navigates away via OAuth redirect.
  }

  return (
    <div className="flex min-h-screen">
      {/* Left — Form */}
      <div className="flex flex-1 flex-col justify-center px-8 py-12 sm:px-16 lg:px-24">
        <div className="mx-auto w-full max-w-sm">
          {/* Logo */}
          <Link href="/" className="mb-10 flex items-center gap-2">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
              <ScanLine className="h-3.5 w-3.5 text-white" />
            </div>
            <span className="text-lg font-bold tracking-tight text-foreground">ConvertScan</span>
          </Link>

          <h1 className="text-2xl font-bold text-foreground">Create your account</h1>
          <p className="mt-1.5 text-sm text-muted-foreground">
            Start improving your conversions today
          </p>

          {/* Google sign-up */}
          <Button
            variant="outline"
            className="mt-8 w-full border-border/50 py-5"
            onClick={handleGoogleSignup}
            disabled={googleLoading || submitting}
