3	import { useQuery } from "@tanstack/react-query";
4	import { createBrowserClient } from "@supabase/ssr";
5	import { FLAG_DEFINITIONS } from "@/hooks/admin/use-feature-flags";
6	
7	function createUntypedClient() {
8	  return createBrowserClient(
9	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
10	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
11	  );
