13	
14	const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
15	  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
16	);
17	
18	async function fetchAllFeatureFlags(): Promise<Record<string, boolean>> {
19	  const supabase = createUntypedClient();
20	  const { data, error } = await supabase
21	    .from("system_config")
22	    .select("value")
23	    .eq("key", "feature_flags")
24	    .single();
25	
26	  if (error && error.code !== "PGRST116") return DEFAULT_FLAGS;
27	
28	  const stored = (data?.value ?? {}) as Record<string, boolean>;
29	  return { ...DEFAULT_FLAGS, ...stored };
30	}
31	
32	export function useFeatureFlag(key: string, defaultValue = true): boolean {
33	  const { data } = useQuery({
34	    queryKey: ["feature-flags"],
35	    queryFn: fetchAllFeatureFlags,
36	    staleTime: 5 * 60 * 1000,
37	    retry: 1,
38	  });
39	
40	  if (data === undefined) {
41	    const flagDef = FLAG_DEFINITIONS.find((f) => f.key === key);
42	    return flagDef?.defaultValue ?? defaultValue;
43	  }
44	
45	  return data[key] ?? defaultValue;
46	}
